import { defineConfig, devices } from "@playwright/test";

// G10-VERIFICATION-PLAYWRIGHT — headless suite over the local production build.
// Exit criterion for gate G10 (product-contract/execution/CURRENT_SLICE.yaml):
// golden journey B10, offline drill, persona tours, negative paths.
export default defineConfig({
  testDir: "./e2e",
  timeout: 60_000,
  expect: { timeout: 10_000 },
  fullyParallel: false, // journey specs mutate shared live data; keep ordering deterministic
  workers: 1,
  retries: 0,
  reporter: [
    ["list"],
    ["html", { outputFolder: "playwright-report", open: "never" }],
    ["json", { outputFile: "test-results/results.json" }],
  ],
  use: {
    baseURL: "http://127.0.0.1:3000",
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
    ...devices["Desktop Chrome"],
  },
  projects: [
    { name: "setup", testMatch: /auth\.setup\.ts/ },
    {
      name: "e2e",
      testMatch: /.*\.spec\.ts/,
      dependencies: ["setup"],
    },
  ],
  webServer: {
    command: "npm run start",
    url: "http://127.0.0.1:3000/login",
    reuseExistingServer: true,
    timeout: 60_000,
  },
});

// Seeded demo personas (supabase/migrations/0011_factory360_gis_ksa_seed.sql;
// credentials as exercised by product-contract/evidence/b10_golden_journey.py).
// G11 will rotate these; update here when rotation lands.
export const PERSONAS = {
  planner: { email: "planner@mim.example", password: "MimPlan!2026", home: "/planning" },
  inspector: { email: "inspector@mim.example", password: "MimField!2026", home: "/field" },
  reviewer: { email: "reviewer@mim.example", password: "MimRev!2026", home: "/reviews" },
} as const;

export type PersonaKey = keyof typeof PERSONAS;

export const storageStatePath = (key: PersonaKey) => `test-results/.auth/${key}.json`;

import { test as setup, expect } from "@playwright/test";
import { PERSONAS, storageStatePath, type PersonaKey } from "./personas";

// Signs each persona in through the real /login UI (SCR-PUB-010) and captures
// storage state so specs start authenticated. Landing is decided by role via
// /launch, never by URL — asserting the role home is itself a persona-tour check.
for (const key of Object.keys(PERSONAS) as PersonaKey[]) {
  const p = PERSONAS[key];
  setup(`authenticate ${key}`, async ({ page }) => {
    await page.goto("/login");
    await page.locator("#email").fill(p.email);
    await page.locator("#pw").fill(p.password);
    await page.getByRole("button", { name: /sign in/i }).click();
    await page.waitForURL((url) => url.pathname.startsWith(p.home), { timeout: 20_000 });
    await expect(page.locator("body")).not.toContainText("ERR-AUTH");
    await page.context().storageState({ path: storageStatePath(key) });
  });
}

import { readFileSync } from "node:fs";
import { join } from "node:path";

// Minimal PostgREST client mirroring product-contract/evidence/b10_golden_journey.py:
// every call runs with the acting persona's own JWT so RLS and triggers stay the
// enforcement under test. Used only to stage sacrificial fixtures (e.g. an assigned
// visit for the offline drill) — journey assertions themselves go through the UI.
const env = readFileSync(join(__dirname, "..", ".env.local"), "utf-8");
const BASE = env.match(/NEXT_PUBLIC_SUPABASE_URL=(.+)/)![1].trim();
const ANON = env.match(/NEXT_PUBLIC_SUPABASE_ANON_KEY=(.+)/)![1].trim();

export async function login(email: string, password: string) {
  const r = await fetch(`${BASE}/auth/v1/token?grant_type=password`, {
    method: "POST",
    headers: { apikey: ANON, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  if (!r.ok) throw new Error(`auth failed for ${email}: ${r.status} ${await r.text()}`);
  const d = await r.json();
  return { jwt: d.access_token as string, userId: d.user.id as string };
}

export async function rest<T = any>(
  method: string,
  path: string,
  jwt: string,
  body?: unknown,
  prefer = "return=representation",
): Promise<{ data: T | null; error: string | null }> {
  const r = await fetch(`${BASE}/rest/v1/${path}`, {
    method,
    headers: {
      apikey: ANON,
      Authorization: `Bearer ${jwt}`,
      "Content-Type": "application/json",
      Prefer: prefer,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const raw = await r.text();
  if (!r.ok) return { data: null, error: `${r.status} ${raw.slice(0, 220)}` };
  return { data: raw ? JSON.parse(raw) : null, error: null };
}

export function must<T>(res: { data: T | null; error: string | null }, step: string): T {
  if (res.error || res.data === null) throw new Error(`${step}: ${res.error ?? "no data"}`);
  return res.data;
}

import { test, expect } from "@playwright/test";
import { PERSONAS } from "./personas";

// Negative paths: authentication (ERR-AUTH-001 — deny with safe message).
test.describe("negative: authentication", () => {
  test("wrong password is denied with a safe banner, no session", async ({ page }) => {
    await page.goto("/login");
    await page.locator("#email").fill(PERSONAS.inspector.email);
    await page.locator("#pw").fill("WrongPassword!0000");
    await page.getByRole("button", { name: /sign in/i }).click();
    const banner = page.locator(".ax-banner--critical[role=alert]");
    await expect(banner).toBeVisible();
    // Safe message: must not leak whether the account exists or echo credentials.
    await expect(banner).not.toContainText(PERSONAS.inspector.email);
    await expect(page).toHaveURL(/\/login/);
  });

  test("unknown account is denied with the same safe shape", async ({ page }) => {
    await page.goto("/login?as=inspector");
    await page.locator("#email").fill("nobody@mim.example");
    await page.locator("#pw").fill("Whatever!2026");
    await page.getByRole("button", { name: /sign in/i }).click();
    await expect(page.locator(".ax-banner--critical[role=alert]")).toBeVisible();
    await expect(page).toHaveURL(/\/login/);
  });

  test("unauthenticated visit to a protected route lands on /login", async ({ page }) => {
    await page.goto("/launch");
    await page.waitForURL(/\/login/, { timeout: 15_000 });
  });
});

import { test, expect } from "@playwright/test";
import { PERSONAS, storageStatePath } from "./personas";
import { login, rest, must } from "./live-rest";

// G10 offline drill (STM-SYNC-001/002, MVP1-FND-005/006): answers and the
// submission queue while offline, replay exactly once on reconnect, no data loss.
// Fixture staging goes over PostgREST with persona JWTs (sacrificial visit,
// same pattern as B10-EV-001); the drill itself is driven through the real UI.

test.use({ storageState: storageStatePath("inspector") });

let inspectionId: string;
let itemIds: Record<string, string>;

test.beforeAll(async () => {
  const planner = await login(PERSONAS.planner.email, PERSONAS.planner.password);
  const inspector = await login(PERSONAS.inspector.email, PERSONAS.inspector.password);

  const fac = must(await rest("GET", "factories?select=id&factory_code=eq.F-1102", planner.jwt), "factory")[0];
  const pkg = must(await rest("GET", "package_versions?select=id&status=eq.published&order=published_at.desc&limit=1", planner.jwt), "package")[0];
  const plan = must(await rest("POST", "visit_plans", planner.jwt, { method: "single", status: "draft", created_by: planner.userId }), "plan")[0];
  const now = new Date();
  const visit = must(await rest("POST", "visits", planner.jwt, {
    visit_plan_id: plan.id, factory_id: fac.id, visit_type: "periodic",
    execution_mode: "physical", planning_status: "draft",
    window_start: new Date(now.getTime() + 3 * 864e5).toISOString(),
    window_end: new Date(now.getTime() + 3 * 864e5 + 4 * 36e5).toISOString(),
    package_version_id: pkg.id,
  }), "visit")[0];
  must(await rest("POST", "assignments", planner.jwt, { visit_id: visit.id, inspector_id: inspector.userId, method: "manual" }, "return=minimal"), "assign");
  must(await rest("PATCH", `visits?id=eq.${visit.id}`, planner.jwt, { planning_status: "published" }, "return=minimal"), "publish");

  const ins = must(await rest("POST", "inspections", inspector.jwt, {
    visit_id: visit.id, package_version_id: pkg.id, status: "in_progress", started_at: now.toISOString(),
  }), "inspection")[0];
  inspectionId = ins.id;

  const items = must(await rest("GET", "inspection_items?select=id,code&code=in.(FS-101,FS-102,EG-201)", inspector.jwt), "items");
  itemIds = Object.fromEntries(items.map((i: { code: string; id: string }) => [i.code, i.id]));
});

test("offline answers queue locally, replay once on reconnect, offline submit never claims success", async ({ page, context }) => {
  await page.goto(`/field/inspection/${inspectionId}`);
  const badge = page.locator(".ax-sync");
  await expect(badge).toBeVisible();

  // --- go offline ---
  await context.setOffline(true);
  await page.evaluate(() => window.dispatchEvent(new Event("offline")));
  await expect(badge).toHaveClass(/ax-sync--offline/);
  await expect(badge).toContainText("Offline — work saved locally");

  // Answer FS-101 while offline; UI reflects it instantly from the local draft.
  const q101 = page.locator(".ipad-q", { hasText: "FS-101" });
  await q101.getByRole("button", { name: /^compliant$/i }).click();
  await expect(q101).toHaveClass(/is-answered/);

  // Answer the rest and submit while still offline (STM-SYNC-001 leg).
  for (const code of ["FS-102", "EG-201"]) {
    const q = page.locator(".ipad-q", { hasText: code });
    await q.getByRole("button", { name: /^compliant$/i }).click();
    await expect(q).toHaveClass(/is-answered/);
  }
  await page.getByRole("button", { name: "Review & submit — immutable v1" }).click();
  // Never claims "submitted" while unsynced — the queued message is explicit.
  await expect(page.locator(".ax-banner").first()).toContainText("Queued — will submit exactly once on reconnect");

  // --- reconnect ---
  await context.setOffline(false);
  await page.evaluate(() => window.dispatchEvent(new Event("online")));
  await expect(badge).toHaveClass(/ax-sync--synced/, { timeout: 30_000 });

  // Server truth: all three responses landed and exactly one immutable v1 exists.
  const inspector = await login(PERSONAS.inspector.email, PERSONAS.inspector.password);
  const resp = must(await rest("GET",
    `checklist_responses?select=item_id,response&inspection_id=eq.${inspectionId}`, inspector.jwt), "responses");
  const values = Object.fromEntries(resp.map((r: { item_id: string; response: { value: string } }) => [r.item_id, r.response.value]));
  for (const code of ["FS-101", "FS-102", "EG-201"]) {
    expect(values[itemIds[code]], `${code} response replayed`).toBe("compliant");
  }
  const subs = must(await rest("GET",
    `submission_versions?select=id,version_number&inspection_id=eq.${inspectionId}`, inspector.jwt), "versions");
  expect(subs.length, "exactly one submission after replay (idempotent)").toBe(1);
  expect(subs[0].version_number).toBe(1);
});

