tool_input.content:
import "./login.css";
import { cookies } from "next/headers";
import LoginClient, { type LoginStrings } from "./LoginClient";

export const dynamic = "force-dynamic";

// SCR-PUB-010 — single national sign-in. Gated behind a simulated Nafath
// (national unified access) step; channel/role is resolved server-side by
// /launch after auth and is never exposed on this screen. Arabic-first
// (KSA public entry point); English via the toggle.
type Locale = "ar" | "en";

async function resolveLocale(): Promise<Locale> {
  const c = await cookies();
  return c.get("locale")?.value === "en" ? "en" : "ar";
}

export default async function Login() {
  const locale = await resolveLocale();
  const ar = locale === "ar";

  const strings: LoginStrings = {
    dir: ar ? "rtl" : "ltr",
    lang: locale,
    brandTitle: ar ? "منصّة التفتيش الصناعي" : "Industrial Inspection Platform",
    brandSub: ar ? "وزارة الصناعة والثروة المعدنية" : "Ministry of Industry & Mineral Resources",
    heroTitle: ar ? "الدخول إلى منصة التفتيش الصناعي" : "Sign in to the inspection platform",
    heroSub: ar ? "دخول آمن وموحّد لجميع مستخدمي المنصة، عبر منصّة نفاذ الوطنية." : "One secure, unified sign-in for every user of the platform, through Nafath — the national unified access.",
    heroPoints: ar
      ? ["التحقق من الهوية عبر نفاذ الوطنية", "كل جلسة دخول موثّقة ومراجَعة", "صلاحياتك تُحدَّد تلقائيًا بحسب دورك"]
      : ["Identity verified through Nafath", "Every session is recorded and reviewable", "Your access is scoped to your role automatically"],
    nidLabel: ar ? "رقم الهوية الوطنية أو الإقامة" : "National ID or Iqama number",
    nidHint: ar ? "10 أرقام" : "10 digits",
    continueViaNafath: ar ? "المتابعة عبر نفاذ" : "Continue with Nafath",
    waitingTitle: ar ? "بانتظار الموافقة في تطبيق نفاذ" : "Waiting for approval in the Nafath app",
    waitingBody: ar ? "افتح تطبيق نفاذ واختر الرقم التالي لإتمام التحقق:" : "Open the Nafath app and select the number below to confirm:",
    simulatedNote: ar
      ? "خطوة تجريبية — ستُستبدل بربط فعلي مع خدمة نفاذ الرسمية عند توفّر التكامل."
      : "Simulated step — will be replaced with a live Nafath integration once the official service is connected.",
    approveSimulated: ar ? "لقد وافقت في التطبيق (تجريبي)" : "I approved in the app (simulated)",
    cancel: ar ? "إلغاء" : "Cancel",
    credentialsTitle: ar ? "إتمام الدخول" : "Complete sign-in",
    credentialsSub: ar ? "تم التحقق من هويتك عبر نفاذ. أكمل الدخول ببيانات حسابك المؤسسي." : "Your identity is verified through Nafath. Complete sign-in with your organizational account.",
    email: ar ? "البريد الإلكتروني" : "Email",
    password: ar ? "كلمة المرور" : "Password",
    signIn: ar ? "تسجيل الدخول" : "Sign in",
    signingIn: ar ? "جارٍ الدخول…" : "Signing in…",
    footer: ar ? "كل إجراء داخل جلستك موثَّق ومراجَع." : "Every action inside your session is recorded and reviewable.",
    backToLanding: ar ? "← الصفحة الرئيسية" : "← Home",
    langHref: ar ? "/locale?set=en" : "/locale?set=ar",
    langLabel: ar ? "English" : "العربية",
  };

  return <LoginClient strings={strings} />;
}

"use client";
import { useState } from "react";
import { supabaseBrowser } from "@/lib/supabase";

// SCR-PUB-010 — single national sign-in, no channel picker. Role/channel is
// resolved server-side by /launch after auth; this screen never mentions
// admin/web/iPad/agent. The Nafath step is a UX simulation (national ID +
// app-approval pattern) — flagged clearly as a placeholder for the future
// Nafath integration — before falling through to the real credential form
// that actually authenticates against Supabase.
export type LoginStrings = {
  dir: "rtl" | "ltr";
  lang: "ar" | "en";
  brandTitle: string;
  brandSub: string;
  heroTitle: string;
  heroSub: string;
  heroPoints: string[];
  nidLabel: string;
  nidHint: string;
  continueViaNafath: string;
  waitingTitle: string;
  waitingBody: string;
  simulatedNote: string;
  approveSimulated: string;
  cancel: string;
  credentialsTitle: string;
  credentialsSub: string;
  email: string;
  password: string;
  signIn: string;
  signingIn: string;
  footer: string;
  backToLanding: string;
  langHref: string;
  langLabel: string;
};

type Step = "nafath" | "waiting" | "credentials";

export default function LoginClient({ strings: s }: { strings: LoginStrings }) {
  const [step, setStep] = useState<Step>("nafath");
  const [nid, setNid] = useState("");
  const [trustNumber] = useState(() => String(10 + Math.floor(Math.random() * 89)));

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  function submitNafath(e: React.FormEvent) {
    e.preventDefault();
    setStep("waiting");
  }

  async function signIn(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true); setError(null);
    const { error } = await supabaseBrowser().auth.signInWithPassword({ email, password });
    setBusy(false);
    if (error) { setError(error.message); return; }  // ERR-AUTH-001: deny with safe message
    // Hard navigation: guarantees the auth cookie is on the request before
    // /launch renders server-side (router.push races the cookie write).
    window.location.assign("/launch");                // role decides the landing, not the URL
  }

  return (
    <main className="lg-page lg-page--split" dir={s.dir} lang={s.lang}>
      <aside className="lg-hero">
        <a className="lg-hero__brand" href="/">
          <span className="ax-shell__brand-mark">IP</span> {s.brandTitle}
        </a>
        <p className="lg-hero__sub">{s.brandSub}</p>
        <h1>{s.heroTitle}</h1>
        <p className="lg-hero__sub">{s.heroSub}</p>
        <ul className="lg-hero__points">
          {s.heroPoints.map(pt => (
            <li key={pt}><span aria-hidden="true">✓</span> {pt}</li>
          ))}
        </ul>
      </aside>

      <div className="lg-formside">
        <div className="lg-stack">
          {step === "nafath" && (
            <form onSubmit={submitNafath} className="ax-surface ax-panel lg-form">
              <div className="ax-shell__brand lg-form__brand">
                <span className="ax-shell__brand-mark">IP</span> {s.brandTitle}
              </div>
              <div className="ax-field">
                <label className="ax-field__label" htmlFor="nid">{s.nidLabel}</label>
                <input id="nid" className="ax-input" type="text" inputMode="numeric" pattern="[0-9]{10}"
                  maxLength={10} placeholder={s.nidHint}
                  value={nid} onChange={e => setNid(e.target.value.replace(/\D/g, "").slice(0, 10))} required />
              </div>
              <button className="ax-btn ax-btn--prominent" disabled={nid.length !== 10}>{s.continueViaNafath}</button>
              <p className="ax-caption lg-nafath__badge">نفاذ · Nafath</p>
            </form>
          )}

          {step === "waiting" && (
            <div className="ax-surface ax-panel lg-form lg-waiting">
              <div className="ax-shell__brand lg-form__brand">
                <span className="ax-shell__brand-mark">IP</span> {s.brandTitle}
              </div>
              <div className="lg-waiting__spinner" aria-hidden="true" />
              <h3>{s.waitingTitle}</h3>
              <p className="ax-caption">{s.waitingBody}</p>
              <div className="lg-waiting__number">{trustNumber}</div>
              <div className="ax-banner ax-banner--info"><div>{s.simulatedNote}</div></div>
              <button className="ax-btn ax-btn--prominent" onClick={() => setStep("credentials")}>{s.approveSimulated}</button>
              <button type="button" className="ax-btn ax-btn--subtle" onClick={() => setStep("nafath")}>{s.cancel}</button>
            </div>
          )}

          {step === "credentials" && (
            <form onSubmit={signIn} className="ax-surface ax-panel lg-form">
              <div className="ax-shell__brand lg-form__brand">
                <span className="ax-shell__brand-mark">IP</span> {s.credentialsTitle}
              </div>
              <p className="ax-caption">{s.credentialsSub}</p>
              <div className="ax-field">
                <label className="ax-field__label" htmlFor="email">{s.email}</label>
                <input id="email" className="ax-input" type="email" value={email} onChange={e => setEmail(e.target.value)} autoComplete="username" required />
              </div>
              <div className="ax-field">
                <label className="ax-field__label" htmlFor="pw">{s.password}</label>
                <input id="pw" className="ax-input" type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" required />
              </div>
              {error && <div className="ax-banner ax-banner--critical" role="alert"><div>{error}</div></div>}
              <button className="ax-btn ax-btn--prominent" disabled={busy}>{busy ? s.signingIn : s.signIn}</button>
              <p className="ax-caption">{s.footer}</p>
            </form>
          )}

          <nav className="lg-switch">
            <a href={s.langHref} lang={s.lang === "ar" ? "en" : "ar"}>{s.langLabel}</a>
            <a href="/">{s.backToLanding}</a>
          </nav>
        </div>
      </div>
    </main>
  );
}

