tool_input.content:
import type { Page } from "@playwright/test";

// SCR-PUB-010 — /login now gates the real credential form behind a simulated
// Nafath (national unified access) step: NID -> waiting-for-app-approval ->
// credentials. Locale defaults to Arabic, so this drives the flow through
// stable ids/classes (#nid, .lg-form, .ax-btn--prominent) rather than copy,
// which would otherwise need to match whichever language rendered.
export async function passNafath(page: Page) {
  await page.locator("#nid").fill("1234567890");
  await page.locator(".lg-form button.ax-btn--prominent").click(); // Continue with Nafath
  await page.locator(".lg-waiting button.ax-btn--prominent").click(); // I approved (simulated)
  await page.locator("#email").waitFor();
}

