  method: "POST", headers: { apikey: ANON, "Content-Type": "application/json" },
  body: JSON.stringify({ email: "planner@mim.example", password: "MimPlan!2026" })
});
const d = await r.json();
const browser = await chromium.launch();
const ctx = await browser.newContext();
await ctx.addCookies([{ name: `sb-iiozvqntawxfwbgffzqu-auth-token`, value: JSON.stringify({
  access_token: d.access_token, refresh_token: d.refresh_token, expires_at: Math.floor(Date.now()/1000)+3600,
  expires_in: 3600, token_type: 'bearer', user: d.user
}), domain: '127.0.0.1', path: '/' }]);
const page = await ctx.newPage();
page.on('console', msg => console.log('CONSOLE:', msg.type(), msg.text()));
page.on('pageerror', err => console.log('PAGEERROR:', err.message));
page.on('request', req => { if (req.method() === 'POST' && req.url().includes('127.0.0.1')) console.log('POST', req.url()); });
await page.goto('http://127.0.0.1:3000/planning/single');
await page.getByPlaceholder(/CR number|Industrial License/i).fill('F-1104');
await page.locator('input[name="factory_id"]').first().check();
await page.getByText(/3 · Confirm location/).waitFor();
await page.locator('input[name="license_number"]').check();
await page.locator('input[name="location_confirmed"]').check();
await page.locator('select[name="package_version_id"]').selectOption({ index: 1 });
const start = new Date(Date.now() + 3 * 864e5).toISOString().slice(0, 16);
await page.locator('input[name="window_start"]').fill(start);
await page.locator('input[name="window_end"]').fill(start);
console.log('BEFORE: lic=', await page.locator('input[name="license_number"]').isChecked(),
  'loc=', await page.locator('input[name="location_confirmed"]').isChecked());

// Instrument: watch for DOM mutations on the license/location inputs
await page.evaluate(() => {
  const lic = document.querySelector('input[name="license_number"]');
  const loc = document.querySelector('input[name="location_confirmed"]');
  window.__log = [];
  for (const [name, el] of [['license', lic], ['location', loc]]) {
    if (!el) { window.__log.push(`${name}: NOT FOUND at instrument time`); continue; }
    const obs = new MutationObserver(muts => {
      for (const m of muts) window.__log.push(`${name} mutation: ${m.type} ${m.attributeName}`);
    });
    obs.observe(el, { attributes: true });
    el.addEventListener('change', () => window.__log.push(`${name} change event fired, checked=${el.checked}`));
  }
  // also watch for the element being removed/replaced
  new MutationObserver(muts => {
    for (const m of muts) {
      for (const n of m.removedNodes) {
        if (n.nodeType === 1 && (n.matches?.('input[name="license_number"]') || n.querySelector?.('input[name="license_number"]'))) {
          window.__log.push('license_number node REMOVED from DOM');
        }
        if (n.nodeType === 1 && (n.matches?.('input[name="location_confirmed"]') || n.querySelector?.('input[name="location_confirmed"]'))) {
          window.__log.push('location_confirmed node REMOVED from DOM');
        }
      }
    }
  }).observe(document.body, { childList: true, subtree: true });
});

console.log('--- clicking submit ---');
await page.getByRole('button', { name: /publish visit/i }).click();
await page.waitForTimeout(2000);
console.log('AFTER: lic=', await page.locator('input[name="license_number"]').isChecked(),
  'loc=', await page.locator('input[name="location_confirmed"]').isChecked());
const log = await page.evaluate(() => window.__log);
console.log('MUTATION LOG:', JSON.stringify(log, null, 2));
await browser.close();
EOF
