"use client";
import { useState } from "react";
import { supabaseBrowser } from "@/lib/supabase";
import { IconFingerprint, IconGovFlag, IconLock, IconEye, IconEyeOff, IconShieldCheck } from "../icons";

// SCR-PUB-010 — national sign-in (client half). Layout mirrors the
// app.industry.sa auth pattern: one centered card, Nafath panel first,
// OR divider, credential form below. The Nafath sub-flow (ID → app-approval
// trust number) is a clearly-flagged simulation kept in the path until the
// official integration lands; credential sign-in is the real Supabase auth.
export type LoginStrings = {
  dir: "rtl" | "ltr";
  lang: "ar" | "en";
  govBanner: string;
  brandTitle: string;
  brandSub: string;
  cardTitle: string;
  cardSub: string;
  nafathTitle: string;
  nafathSub: string;
  or: string;
  idLabel: string;
  idPlaceholder: string;
  pwLabel: string;
  pwPlaceholder: string;
  showPw: string;
  hidePw: string;
  signIn: string;
  signingIn: string;
  nidLabel: string;
  nidHint: string;
  continueBtn: string;
  back: string;
  waitingTitle: string;
  waitingBody: string;
  simulatedNote: string;
  approveSimulated: string;
  verifiedBanner: string;
  footTrust: string;
  footSecure: string;
  backToLanding: string;
  langHref: string;
  langLabel: string;
};

type View = "methods" | "nafath-id" | "nafath-waiting";

export default function LoginClient({ strings: s }: { strings: LoginStrings }) {
  const [view, setView] = useState<View>("methods");
  const [nafathVerified, setNafathVerified] = useState(false);
  const [nid, setNid] = useState("");
  const [trustNumber] = useState(() => String(10 + Math.floor(Math.random() * 89)));

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function signIn(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true); setError(null);
    const { error } = await supabaseBrowser().auth.signInWithPassword({ email, password });
    setBusy(false);
    if (error) { setError(error.message); return; }  // ERR-AUTH-001: deny with safe message
    // Hard navigation: guarantees the auth cookie is on the request before
    // /launch renders server-side (router.push races the cookie write).
    window.location.assign("/launch");                // role decides the landing, not the URL
  }

  return (
    <div className="lg-page" dir={s.dir} lang={s.lang}>
      <div className="lg-govbar">
        <span className="lg-govbar__flag" aria-hidden="true"><IconGovFlag size={14} /></span>
        {s.govBanner}
      </div>

      <header className="lg-topbar">
        <a className="lg-topbar__brand" href="/">
          <span className="ax-shell__brand-mark">IP</span>
          <span className="lg-topbar__brandtext">
            <strong>{s.brandTitle}</strong>
            <small>{s.brandSub}</small>
          </span>
        </a>
        <nav className="lg-topbar__actions">
          <a href={s.langHref} lang={s.lang === "ar" ? "en" : "ar"}>{s.langLabel}</a>
          <a href="/">{s.backToLanding}</a>
        </nav>
      </header>

      <main className="lg-center">
        <div className="lg-card">
          {view === "methods" && (
            <>
              <h1 className="lg-card__title">{s.cardTitle}</h1>
              <p className="lg-card__sub">{s.cardSub}</p>

              {nafathVerified && (
                <div className="ax-banner ax-banner--success" role="status"><div>{s.verifiedBanner}</div></div>
              )}

              <button type="button" className="lg-nafath" onClick={() => setView("nafath-id")}>
                <span className="lg-nafath__mark" aria-hidden="true"><IconFingerprint size={26} /></span>
                <span className="lg-nafath__text">
                  <strong>{s.nafathTitle}</strong>
                  <span>{s.nafathSub}</span>
                </span>
              </button>

              <div className="lg-or" role="separator" aria-label={s.or}><span>{s.or}</span></div>

              <form onSubmit={signIn} className="lg-credentials">
                <div className="ax-field">
                  <label className="ax-field__label" htmlFor="email">{s.idLabel}</label>
                  <input id="email" className="ax-input" type="email" placeholder={s.idPlaceholder}
                    value={email} onChange={e => setEmail(e.target.value)} autoComplete="username" required />
                </div>
                <div className="ax-field">
                  <label className="ax-field__label" htmlFor="pw">{s.pwLabel}</label>
                  <div className="lg-pwwrap">
                    <input id="pw" className="ax-input" type={showPw ? "text" : "password"} placeholder={s.pwPlaceholder}
                      value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" required />
                    <button type="button" className="lg-pwtoggle" onClick={() => setShowPw(v => !v)}
                      aria-label={showPw ? s.hidePw : s.showPw}>
                      {showPw ? <IconEyeOff /> : <IconEye />}
                    </button>
                  </div>
                </div>
                {error && <div className="ax-banner ax-banner--critical" role="alert"><div>{error}</div></div>}
                <button className="ax-btn ax-btn--prominent lg-submit" disabled={busy}>{busy ? s.signingIn : s.signIn}</button>
              </form>
            </>
          )}

          {view === "nafath-id" && (
            <form onSubmit={e => { e.preventDefault(); setView("nafath-waiting"); }} className="lg-credentials">
              <h1 className="lg-card__title">{s.nafathTitle}</h1>
              <p className="lg-card__sub">{s.nafathSub}</p>
              <div className="ax-field">
                <label className="ax-field__label" htmlFor="nid">{s.nidLabel}</label>
                <input id="nid" className="ax-input" type="text" inputMode="numeric" pattern="[0-9]{10}"
                  maxLength={10} placeholder={s.nidHint}
                  value={nid} onChange={e => setNid(e.target.value.replace(/\D/g, "").slice(0, 10))} required />
              </div>
              <button className="ax-btn ax-btn--prominent lg-submit" disabled={nid.length !== 10}>{s.continueBtn}</button>
              <button type="button" className="ax-btn lg-submit" onClick={() => setView("methods")}>{s.back}</button>
            </form>
          )}

          {view === "nafath-waiting" && (
            <div className="lg-waiting">
              <div className="lg-waiting__spinner" aria-hidden="true" />
              <h1 className="lg-card__title">{s.waitingTitle}</h1>
              <p className="lg-card__sub">{s.waitingBody}</p>
              <div className="lg-waiting__number">{trustNumber}</div>
              <div className="ax-banner ax-banner--info"><div>{s.simulatedNote}</div></div>
              <button className="ax-btn ax-btn--prominent lg-submit"
                onClick={() => { setNafathVerified(true); setView("methods"); }}>
                {s.approveSimulated}
              </button>
              <button type="button" className="ax-btn lg-submit" onClick={() => setView("methods")}>{s.back}</button>
            </div>
          )}
        </div>

        <div className="lg-trust">
          <span><IconShieldCheck size={15} /> {s.footTrust}</span>
          <span><IconLock size={14} /> {s.footSecure}</span>
        </div>
      </main>
    </div>
  );
}

import type { Page } from "@playwright/test";

// SCR-PUB-010 — /login shows the credential form directly (view="methods");
// Nafath is an optional sign-in method (a button into a separate NID ->
// waiting-for-app-approval sub-flow), not a mandatory gate in front of
// credentials. #email/#pw are present on initial render, so no navigation
// through Nafath is needed to sign in with a password.
export async function waitForCredentialsForm(page: Page) {
  await page.locator("#email").waitFor();
}

// Locale defaults to Arabic, so target the credentials form structurally
// (id + class) instead of by button label, which would need to match
// whichever language rendered.
export async function submitCredentials(page: Page) {
  await page.locator("form:has(#email) button.ax-btn--prominent").click();
}

/* ============================================================================
   MIM ASTRYX — NATIONAL SIGN-IN (SCR-PUB-010)
   Pattern: app.industry.sa auth — centered card on a soft tinted canvas,
   Nafath panel first, OR divider, credential form below.
   GLOBAL COLOR LAW: tokens only — every color is var(--ax-*) or a color-mix()
   of approved tokens. No raw values outside tokens.css.
   ========================================================================== */

.lg-page { min-block-size: 100dvh; display: flex; flex-direction: column;
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--ax-color-primary) 7%, var(--ax-color-canvas)),
      var(--ax-color-canvas) 55%);
  color: var(--ax-color-text); font: var(--ax-text-body); }

/* ---- official-government strip (gov.sa pattern) ---- */
.lg-govbar { display: flex; align-items: center; justify-content: center; gap: var(--ax-space-100);
  padding: 6px var(--ax-space-200); font: var(--ax-text-caption);
  background: var(--ax-color-surface); border-block-end: 1px solid var(--ax-color-border);
  color: var(--ax-color-text-secondary); }
.lg-govbar__flag { display: inline-flex; color: var(--ax-color-primary); }

/* ---- top bar ---- */
.lg-topbar { display: flex; align-items: center; justify-content: space-between;
  padding: var(--ax-space-150) clamp(16px, 4vw, 48px); }
.lg-topbar__brand { display: flex; align-items: center; gap: var(--ax-space-150);
  text-decoration: none; color: inherit; }
.lg-topbar__brandtext { display: flex; flex-direction: column; line-height: 1.25; }
.lg-topbar__brandtext strong { font-weight: 700; letter-spacing: -0.01em; font-size: 15px; }
.lg-topbar__brandtext small { font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }
.lg-topbar__actions { display: flex; gap: var(--ax-space-100); }
.lg-topbar__actions a { display: inline-flex; align-items: center; padding: 5px 12px;
  border-radius: var(--ax-radius-full); border: 1px solid var(--ax-color-border);
  background: var(--ax-color-surface); color: var(--ax-color-text); text-decoration: none;
  font: var(--ax-text-caption);
  transition: border-color var(--ax-motion-fast), background var(--ax-motion-fast); }
.lg-topbar__actions a:hover { border-color: var(--ax-color-primary-weak); background: var(--ax-color-primary-tint); }

/* ---- centered card ---- */
.lg-center { flex: 1; display: flex; flex-direction: column; align-items: center;
  justify-content: center; gap: var(--ax-space-200); padding: var(--ax-space-400) var(--ax-space-200); }
.lg-card { inline-size: min(560px, 100%); background: var(--ax-color-surface);
  border: 1px solid var(--ax-color-border); border-radius: var(--ax-radius-large);
  box-shadow: var(--ax-shadow-overlay); padding: clamp(24px, 5vw, 44px);
  display: flex; flex-direction: column; gap: var(--ax-space-250); }
.lg-card__title { font: var(--ax-text-title); text-align: center; letter-spacing: -0.01em; }
.lg-card__sub { font: var(--ax-text-body); color: var(--ax-color-text-secondary); text-align: center; }

/* ---- Nafath panel (primary method) ---- */
.lg-nafath { display: flex; align-items: center; gap: var(--ax-space-200); text-align: start;
  padding: var(--ax-space-200) var(--ax-space-250);
  border: 1px solid color-mix(in srgb, var(--ax-color-primary) 30%, var(--ax-color-border));
  border-radius: var(--ax-radius-standard);
  background: var(--ax-color-primary-tint); cursor: pointer; font: inherit; color: inherit;
  transition: border-color var(--ax-motion-fast), box-shadow var(--ax-motion-fast); }
.lg-nafath:hover { border-color: var(--ax-color-primary); box-shadow: var(--ax-shadow-raised); }
.lg-nafath:focus-visible { outline: none; box-shadow: var(--ax-focus-ring); }
.lg-nafath__mark { display: grid; place-items: center; inline-size: 48px; block-size: 48px;
  border-radius: var(--ax-radius-standard); flex-shrink: 0;
  background: var(--ax-color-surface); color: var(--ax-color-primary);
  border: 1px solid color-mix(in srgb, var(--ax-color-primary) 24%, var(--ax-color-border)); }
.lg-nafath__text { display: flex; flex-direction: column; gap: 2px; }
.lg-nafath__text strong { font: var(--ax-text-body-strong); color: var(--ax-color-primary-strong); }
.lg-nafath__text span { font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }

/* ---- OR divider ---- */
.lg-or { display: flex; align-items: center; gap: var(--ax-space-200);
  color: var(--ax-color-text-secondary); font: var(--ax-text-caption); }
.lg-or::before, .lg-or::after { content: ""; flex: 1; block-size: 1px; background: var(--ax-color-border); }

/* ---- credential form ---- */
.lg-credentials { display: flex; flex-direction: column; gap: var(--ax-space-200); }
.lg-credentials .ax-field { max-inline-size: none; }
.lg-pwwrap { position: relative; }
.lg-pwwrap .ax-input { padding-inline-end: 44px; inline-size: 100%; }
.lg-pwtoggle { position: absolute; inset-block-start: 50%; inset-inline-end: 8px;
  transform: translateY(-50%); display: grid; place-items: center;
  inline-size: 32px; block-size: 32px; border: 0; border-radius: var(--ax-radius-small);
  background: transparent; color: var(--ax-color-text-secondary); cursor: pointer; }
.lg-pwtoggle:hover { background: var(--ax-color-neutral-tint); color: var(--ax-color-text); }
.lg-submit { inline-size: 100%; }

/* ---- Nafath waiting (simulated app approval) ---- */
.lg-waiting { display: flex; flex-direction: column; align-items: center; gap: var(--ax-space-200); text-align: center; }
.lg-waiting__spinner { inline-size: 36px; block-size: 36px; border-radius: 50%;
  border: 3px solid var(--ax-color-primary-tint); border-block-start-color: var(--ax-color-primary);
  animation: lg-spin 900ms linear infinite; }
@keyframes lg-spin { to { transform: rotate(360deg); } }
.lg-waiting__number { font: var(--ax-text-display); font-feature-settings: var(--ax-numeric-features);
  letter-spacing: .08em; padding: var(--ax-space-150) var(--ax-space-400);
  border-radius: var(--ax-radius-standard);
  background: var(--ax-color-primary-tint); color: var(--ax-color-primary-strong); }
@media (prefers-reduced-motion: reduce) { .lg-waiting__spinner { animation: none; } }

/* ---- trust line under the card ---- */
.lg-trust { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--ax-space-300);
  font: var(--ax-text-caption); color: var(--ax-color-text-secondary); }
.lg-trust span { display: inline-flex; align-items: center; gap: 6px; }
.lg-trust svg { color: var(--ax-color-primary); }

