const { chromium } = require('@playwright/test');
const fs = require('fs');
const env = fs.readFileSync('.env.local','utf-8');
const BASE = env.match(/NEXT_PUBLIC_SUPABASE_URL=(.+)/)[1].trim();
const ANON = env.match(/NEXT_PUBLIC_SUPABASE_ANON_KEY=(.+)/)[1].trim();
(async () => {
  const r = await fetch(BASE+'/auth/v1/token?grant_type=password', {method:'POST', headers:{apikey:ANON,'Content-Type':'application/json'}, body: JSON.stringify({email:'planner@mim.example', password:'MimPlan!2026'})});
  const planner = await r.json();
  const r2 = await fetch(BASE+'/auth/v1/token?grant_type=password', {method:'POST', headers:{apikey:ANON,'Content-Type':'application/json'}, body: JSON.stringify({email:'inspector@mim.example', password:'MimField!2026'})});
  const inspector = await r2.json();

  // pick a clean factory same way the spec does
  const facR = await fetch(BASE+'/rest/v1/factories?select=id,factory_code,name&order=factory_code', {headers:{apikey:ANON, Authorization:'Bearer '+planner.access_token}});
  const factories = await facR.json();
  const actR = await fetch(BASE+'/rest/v1/visits?select=factory_id&visit_type=eq.periodic&planning_status=in.(draft,published,returned)', {headers:{apikey:ANON, Authorization:'Bearer '+planner.access_token}});
  const active = await actR.json();
  const busy = new Set(active.map(v=>v.factory_id));
  const factory = factories.find(f => !busy.has(f.id) && f.factory_code !== 'F-1102');
  console.log('picked factory:', factory.factory_code, factory.name, factory.id);

  const pkgR = await fetch(BASE+'/rest/v1/package_versions?select=id&status=eq.published&order=published_at.desc&limit=1', {headers:{apikey:ANON, Authorization:'Bearer '+planner.access_token}});
  const pkg = (await pkgR.json())[0];

  const planR = await fetch(BASE+'/rest/v1/visit_plans', {method:'POST', headers:{apikey:ANON, Authorization:'Bearer '+planner.access_token, 'Content-Type':'application/json', Prefer:'return=representation'}, body: JSON.stringify({method:'single', status:'draft', created_by: planner.user.id})});
  const plan = (await planR.json())[0];
  const now = new Date();
  const visitR = await fetch(BASE+'/rest/v1/visits', {method:'POST', headers:{apikey:ANON, Authorization:'Bearer '+planner.access_token, 'Content-Type':'application/json', Prefer:'return=representation'}, body: JSON.stringify({visit_plan_id: plan.id, factory_id: factory.id, visit_type:'periodic', execution_mode:'physical', planning_status:'draft', window_start: new Date(now.getTime()+3*864e5).toISOString(), window_end: new Date(now.getTime()+3*864e5+4*36e5).toISOString(), package_version_id: pkg.id})});
  const visit = (await visitR.json())[0];
  await fetch(BASE+'/rest/v1/assignments', {method:'POST', headers:{apikey:ANON, Authorization:'Bearer '+planner.access_token, 'Content-Type':'application/json', Prefer:'return=minimal'}, body: JSON.stringify({visit_id: visit.id, inspector_id: inspector.user.id, method:'manual'})});
  await fetch(BASE+'/rest/v1/visits?id=eq.'+visit.id, {method:'PATCH', headers:{apikey:ANON, Authorization:'Bearer '+planner.access_token, 'Content-Type':'application/json', Prefer:'return=minimal'}, body: JSON.stringify({planning_status:'published'})});

  const browser = await chromium.launch();
  const page = await (await browser.newContext()).newPage();
  page.on('console', m => { if (m.type()==='error') console.log('CONSOLE ERROR:', m.text()); });
  page.on('pageerror', e => console.log('PAGE ERROR:', e.message, '\n', e.stack));

  await page.goto('http://127.0.0.1:3000/login');
  await page.locator('#nid').fill('1234567890');
  await page.locator('.lg-form button.ax-btn--prominent').click();
  await page.locator('.lg-waiting button.ax-btn--prominent').click();
  await page.locator('#email').waitFor();
  await page.locator('#email').fill('inspector@mim.example');
  await page.locator('#pw').fill('MimField!2026');
  await page.locator('form:has(#email) button.ax-btn--prominent').click();
  await page.waitForURL(u => u.pathname.startsWith('/field'), {timeout: 20000});

  await page.goto('http://127.0.0.1:3000/field/'+visit.id);
  await page.waitForTimeout(2500);
  console.log('page content snippet:', (await page.locator('body').innerText()).slice(0,300));
  await browser.close();
})();
